using System;using System.Security.Cryptography;using System.Text;namespace AshkanJobCenter.Core{public static class Security{public static string Hash(string password,string salt){using(var sha=SHA256.Create()){var b=sha.ComputeHash(Encoding.UTF8.GetBytes(salt+"|"+password));return Convert.ToBase64String(b);}}public static string Salt(){var b=new byte[24];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b);}public static bool Strong(string p){return !string.IsNullOrWhiteSpace(p)&&p.Length>=8;}}}